"""Coordinate two independent warm hosts; every barrier precedes its timer."""
import hashlib
import json
import os
from pathlib import Path
import selectors
import signal
import statistics
import subprocess
import time
import traceback

REPO=Path('/Users/jakefitzgerald/.codex/worktrees/3c6b/text-to-cad')
PYTHON=Path('/Users/jakefitzgerald/robots/text-to-cad/.venv/bin/python')
LOGS=Path('/private/tmp/cadgen-performance-20260910')
REPORTS=REPO/'scripts/bench/cadgen-performance/results'
HOST=LOGS/'run-ready-sibling-unseen-v2-host.py'
OUT=REPORTS/'ready-sibling-unseen-v2-paired-proof-20260910.json'


class Host:
    def __init__(self, condition):
        self.condition=condition
        self.buffer=b''
        self.daemon=None
        self.log=(LOGS/f'ready-sibling-unseen-v2-{condition}-host.log').open('wb')
        env={k:v for k,v in os.environ.items() if not k.startswith('CADGEN_') and k not in {'PYTHONPATH','NODE_PATH','NODE_OPTIONS'}}
        env.update(PYTHONPATH=str(REPO/'packages/cadgen/src'),PYTHONDONTWRITEBYTECODE='1')
        self.process=subprocess.Popen([str(PYTHON),str(HOST),condition],cwd=REPO,env=env,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,bufsize=0)
        self.selector=selectors.DefaultSelector()
        self.selector.register(self.process.stdout,selectors.EVENT_READ)
    def next(self):
        deadline=time.monotonic()+120
        while True:
            if b'\n' in self.buffer:
                raw,self.buffer=self.buffer.split(b'\n',1)
                try:data=json.loads(raw)
                except (ValueError,UnicodeDecodeError):continue
                if data.get('control')=='ownedDaemon':
                    self.daemon=data['pid']
                if data.get('control')=='ready':return data
                continue
            remaining=deadline-time.monotonic()
            if remaining<=0:raise TimeoutError(f'{self.condition} host stalled')
            if not self.selector.select(min(remaining,5)):continue
            payload=os.read(self.process.stdout.fileno(),65536)
            if not payload:
                code=self.process.wait(timeout=5)
                if code:raise RuntimeError(f'{self.condition} host failed {code}; see its log')
                return None
            self.log.write(payload);self.log.flush()
            self.buffer+=payload
    def grant(self, label):
        self.process.stdin.write((label+'\n').encode('utf-8'))
        self.process.stdin.flush()
    def close(self):
        if self.process.stdin and not self.process.stdin.closed:self.process.stdin.close()
        if self.process.poll() is None:
            try:self.process.wait(timeout=30)
            except subprocess.TimeoutExpired:
                self.process.terminate()
                try:self.process.wait(timeout=30)
                except subprocess.TimeoutExpired:
                    self.process.kill();self.process.wait(timeout=5)
                    # Only the child daemon PID this owned host announced is eligible.
                    if self.daemon:
                        try:os.kill(self.daemon,signal.SIGTERM)
                        except ProcessLookupError:pass
        self.selector.close();self.log.close()


def main():
    assert not OUT.exists()
    proof={'complete':False,'startedUtc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime()),'grants':[],'qualification':'Two independent root interpreters, stores and2worker/0spare child daemons. Inputs/variants match exactly. One complete call at a time; condition order alternates. Each host primes the same two geometry and two placement values, then sees107/108/109 once. Barriers precede timers; no source/body/native work overlaps between timed calls. Six unseen measurements total, with three exact input/STEP pairs. This is a scratch counterfactual, not shipped runtime.'}
    hosts={}
    try:
        for condition in ('ordinary','prepared'):hosts[condition]=Host(condition)
        ready={condition:host.next() for condition,host in hosts.items()}
        for ordinal in range(16):
            a,b=ready['ordinary'],ready['prepared']
            assert a and b and a==b,(ordinal,a,b)
            order=('ordinary','prepared') if ordinal%2==0 else ('prepared','ordinary')
            # Reverse the first condition for the middle unseen input too.
            if ordinal==12:order=('prepared','ordinary')
            for condition in order:
                proof['grants'].append({'ordinal':ordinal,'condition':condition,'run':a['run'],'variant':a['variant'],'utc':time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime())})
                hosts[condition].grant(a['run'])
                ready[condition]=hosts[condition].next()
        assert all(value is None for value in ready.values())
        reports={c:json.loads((REPORTS/f'ready-sibling-unseen-v2-{c}-20260910.json').read_text(encoding='utf-8')) for c in hosts}
        host_proofs={c:json.loads((REPORTS/f'ready-sibling-unseen-v2-{c}-proof-20260910.json').read_text(encoding='utf-8')) for c in hosts}
        for c,data in host_proofs.items():
            assert data['complete'] and data['ownedDaemonStopped'] and data['sourcesRestored'] and data['runtimeUnchanged'],(c,data)
        fingerprints={data['metadata']['sourceFingerprint'] for data in reports.values()}
        assert len(fingerprints)==1
        proof['sourceFingerprint']=next(iter(fingerprints))
        checks=[]
        for ordinary,prepared in zip(reports['ordinary']['runs'],reports['prepared']['runs']):
            assert ordinary['run']==prepared['run'] and ordinary['variant']==prepared['variant']
            outputs=[list(row['actualOutputSha256'].values()) for row in (ordinary,prepared)]
            assert outputs[0]==outputs[1] and len(outputs[0])==1
            assert ordinary['childPinCheckPassed'] and prepared['childPinCheckPassed']
            checks.append({'run':ordinary['run'],'actualRootStepSha256':outputs[0][0],'exactMatch':True,'both9ChildPinChecks':True})
        proof['exactPairs']=checks
        summaries=[]
        for condition,report in reports.items():
            rows=[r for r in report['runs'] if r['novelEdit']]
            assert len(rows)==3 and all(r['firstOutputDigestInStudy'] for r in rows)
            summaries.append({'condition':condition,'count':3,'medianTotalMs':statistics.median(r['milliseconds'] for r in rows),'medianPreviewMs':statistics.median(r['firstPreviewMs'] for r in rows),'medianRootBodyMs':statistics.median(s['milliseconds'] for r in rows for s in r['stages'] if s['label'].startswith('run step model ') and s['label'].endswith('/planetary_gear_assembly.py')),'samples':[{'run':r['run'],'milliseconds':r['milliseconds'],'previewMs':r['firstPreviewMs'],'counters':r['counterfactual']['counters']} for r in rows]})
        proof['summary']=summaries
        proof['hostProofs']={c:f'ready-sibling-unseen-v2-{c}-proof-20260910.json' for c in hosts}
        proof['complete']=True
    except BaseException:
        proof['failure']=traceback.format_exc()
        raise
    finally:
        for host in hosts.values():host.close()
        proof['hostExits']={c:h.process.returncode for c,h in hosts.items()}
        proof['completedUtc']=time.strftime('%Y-%m-%dT%H:%M:%SZ',time.gmtime())
        proof['driverSource']=Path(__file__).read_text(encoding='utf-8')
        proof['driverSha256']=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
        OUT.write_text(json.dumps(proof,indent=2,sort_keys=True)+'\n',encoding='utf-8')


if __name__=='__main__':main()
